{
  "name": "RPLIDAR激光雷达",
  "name_en": "RPLIDAR LiDAR",
  "manufacturer": "",
  "description": "一款通过串口连接的二维旋转式激光雷达，可控制电机转速并启动标准扫描或快速扫描，采集距离点数据并进行实时可视化，适用于环境感知、定位建图和障碍检测等实验。",
  "description_en": "A serial-connected 2D rotating LiDAR that can control motor speed and run standard or express scans to collect distance points with real-time visualization, suitable for experiments in environment sensing, localization and mapping, and obstacle detection.",
  "tag_hints": [
    "2D lidar",
    "serial communication",
    "rotating scan",
    "distance point cloud",
    "motor speed control",
    "environment mapping",
    "real-time scan visualization"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接激光雷达串口并初始化显示环境。",
      "description_en": "Connect to the LiDAR serial port and initialize the display environment."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开激光雷达与计算机的连接。",
      "description_en": "Disconnect the LiDAR from the computer."
    },
    {
      "action_name": "auto-add_checksum",
      "description": "为发送给设备的命令字节串计算并附加校验和。",
      "description_en": "Calculate and append a checksum to a command byte string sent to the device."
    },
    {
      "action_name": "auto-drawPoints",
      "description": "在可视化窗口中绘制最新扫描点、坐标轴和状态信息。",
      "description_en": "Draw the latest scan points, coordinate axes, and status information in the visualization window."
    },
    {
      "action_name": "auto-getControlInputs",
      "description": "读取并处理扫描显示界面的用户控制输入。",
      "description_en": "Read and process user control inputs for the scan display interface."
    },
    {
      "action_name": "auto-start_standard_scan",
      "description": "启动标准扫描并记录采集到的点数据。",
      "description_en": "Start a standard scan and record the collected point data."
    },
    {
      "action_name": "auto-calcAndAddPoints",
      "description": "根据原始距离和角度增量计算点坐标并加入扫描结果。",
      "description_en": "Calculate point coordinates from raw distances and angular increments and add them to the scan result."
    },
    {
      "action_name": "auto-readCabin1or3",
      "description": "解析快速扫描数据中的cabin 1或3数据段。",
      "description_en": "Parse cabin 1 or 3 data segments from express scan data."
    },
    {
      "action_name": "auto-readCabin2or4",
      "description": "解析快速扫描数据中的cabin 2或4数据段。",
      "description_en": "Parse cabin 2 or 4 data segments from express scan data."
    },
    {
      "action_name": "auto-readCabin5",
      "description": "解析快速扫描数据中的cabin 5数据段。",
      "description_en": "Parse cabin 5 data segments from express scan data."
    },
    {
      "action_name": "auto-calcDist",
      "description": "根据原始快速扫描参数计算距离值。",
      "description_en": "Calculate a distance value from raw express scan parameters."
    },
    {
      "action_name": "auto-calcDelta",
      "description": "根据原始快速扫描参数计算角度增量。",
      "description_en": "Calculate an angular increment from raw express scan parameters."
    },
    {
      "action_name": "auto-start_express_scan",
      "description": "启动快速扫描并解析采集到的数据。",
      "description_en": "Start an express scan and parse the acquired data."
    },
    {
      "action_name": "auto-start_motor_max",
      "description": "将电机设置为最高转速。",
      "description_en": "Set the motor to its maximum rotation speed."
    },
    {
      "action_name": "auto-start_motor_34",
      "description": "将电机设置为约75%转速。",
      "description_en": "Set the motor to about 75% rotation speed."
    },
    {
      "action_name": "auto-start_motor_half",
      "description": "将电机设置为约50%转速。",
      "description_en": "Set the motor to about 50% rotation speed."
    },
    {
      "action_name": "auto-start_motor_14",
      "description": "将电机设置为约25%转速。",
      "description_en": "Set the motor to about 25% rotation speed."
    },
    {
      "action_name": "auto-start_motor_slow",
      "description": "将电机设置为最低可用转速。",
      "description_en": "Set the motor to the minimum usable rotation speed."
    },
    {
      "action_name": "auto-stop_motor",
      "description": "停止电机转动。",
      "description_en": "Stop the motor rotation."
    },
    {
      "action_name": "auto-stop_scan",
      "description": "停止扫描数据传输。",
      "description_en": "Stop scan data transmission."
    },
    {
      "action_name": "auto-reset",
      "description": "重置设备。",
      "description_en": "Reset the device."
    },
    {
      "action_name": "auto-get_device_health",
      "description": "获取设备健康状态。",
      "description_en": "get device health status"
    },
    {
      "action_name": "auto-get_device_info",
      "description": "获取设备信息。",
      "description_en": "get device information"
    },
    {
      "action_name": "auto-get_sample_rate",
      "description": "获取默认采样率。",
      "description_en": "get default sample rate"
    }
  ]
}

